mapper.select:
SELECT u.user_id AS userId, u.user_name AS userName, d.dept_name AS deptName, p.post_name AS postName, ROUND(100 + SUM(s.score) / COUNT(DISTINCT s.batch_no), 2) AS totalScore, COUNT(DISTINCT s.batch_no) AS itemCount FROM kpi_score s JOIN sys_user u ON u.user_id = s.user_id JOIN sys_dept d ON u.dept_id = d.dept_id LEFT JOIN sys_user_post up ON u.user_id = up.user_id LEFT JOIN sys_post p ON up.post_id = p.post_id WHERE s.batch_no IN
#{m}
AND u.dept_id = #{deptId}
AND up.post_id = #{postId}
GROUP BY u.user_id, u.user_name, d.dept_name, p.post_name HAVING COUNT(DISTINCT s.batch_no) > 0 ORDER BY totalScore DESC

SELECT * FROM kpi_score
WHERE user_id = #{userId}
AND batch_no IN

    #{m}

ORDER BY batch_no, id

SELECT k.batch_no AS batchNo, u.user_name AS userName, ki.name AS itemName, k.score, k.remark FROM kpi_score k JOIN sys_user u ON k.user_id = u.user_id JOIN kpi_item ki ON k.item_id = ki.id LEFT JOIN sys_user_post up ON u.user_id = up.user_id LEFT JOIN sys_post p ON up.post_id = p.post_id WHERE 1=1
AND k.batch_no IN
#{month}
AND u.dept_id = #{deptId}
AND up.post_id = #{postId}
ORDER BY k.batch_no, u.user_name

SELECT DISTINCT k.user_id
FROM kpi_score k
JOIN sys_user u ON k.user_id = u.user_id
WHERE k.batch_no = #{batchNo}
AND u.dept_id = #{deptId}

mapper.update:
update kpi_score
user_id = #{userId}, item_id = #{itemId}, score = #{score, jdbcType=DECIMAL}, remark = #{remark, jdbcType=VARCHAR}, batch_no = #{batchNo}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, source_record_id = #{sourceRecordId},
where id = #{id}

mapper.delete:
    DELETE FROM kpi_score
WHERE user_id = (SELECT user_id FROM sys_user WHERE user_name = #{userName})
  AND remark = #{remark}
  AND batch_no = DATE_FORMAT(#{checkDate}, '%Y-%m')
  AND item_id IN (
      SELECT id FROM kpi_item WHERE dept_id = #{deptId}
  )
LIMIT 1
